from datetime import date
from invoicing.api import get_invoice_handler, list_invoices_handler
from invoicing.invoice import Invoice, LineItem
from invoicing.service import InvoiceService
from invoicing.store import InvoiceStore

def test_list_invoices():
    s = InvoiceService(InvoiceStore())
    s.create(Invoice("A1", "asha", [LineItem("pen", 1, 10000)], date(2026, 9, 1)))
    s.create(Invoice("A2", "asha", [LineItem("pad", 1, 9900)], date(2026, 9, 2)))
    status, body = list_invoices_handler(s, "asha")
    assert status == 200 and body == [
        {"id": "A1", "created": "2026-09-01", "total": 11800},
        {"id": "A2", "created": "2026-09-02", "total": 9900},
    ]
